def rotate_raster(S,ang,cr,cc,offr=0,offc=0):
 a=math.radians(ang); P=[]
 for r,c in S:
  x=c-cc; y=-(r-cr)
  xx=x*math.cos(a)-y*math.sin(a); yy=x*math.sin(a)+y*math.cos(a)
  P.append((round(cr-yy+offr),round(cc+xx+offc)))
 if len(set(P))<len(S):return None
 mr=min(r for r,c in P); mc=min(c for r,c in P)
 return frozenset((r-mr,c-mc) for r,c in P)
