import re

def parse_demo(text):
 sections={}
 for tag in ['input','output']:
  m=re.search(rf'Demo pair \d+ {tag} \(\d+x\d+\):\n((?:[0-9 ]+\n)+)',text)
  lines=m.group(1).strip().splitlines()
  sections[tag]=[list(map(int,l.split())) for l in lines]
 return sections
